import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Highlight } from "@/components/ui/highlight"
import { Icon } from "@/components/ui/icon"
import { Sticker } from "@/components/ui/sticker"
import { dollars, perMonth, type Period, type Tier } from "@/components/blocks/pricing-01/components/pricing-01-data"
import { cn } from "@/lib/utils"

export function Pricing01Card({ id, tier, period, chosen, onChoose }: { id: string; tier: Tier; period: Period; chosen: boolean; onChoose: () => void }) {
  const free = tier.monthly === 0
  const title = `${id}-title`
  return (
    <Card
      as="article"
      aria-labelledby={title}
      stock={tier.popular ? "card" : "paper"}
      tape="top"
      tapeKind={tier.tape}
      seed={`price-${tier.id}`}
      data-popular={tier.popular ? "" : undefined}
      className={cn("relative h-full", tier.popular && "@4xl/pricing:-my-4 @4xl/pricing:pt-10 @4xl/pricing:pb-10")}
    >
      {tier.popular ? <Sticker name="first-place" size={76} rotate={10} seed="popular" className="absolute -end-2 -top-9 z-10 @4xl/pricing:-end-5" /> : null}
      <CardHeader>
        <CardTitle id={title} role="heading" aria-level={3} className="text-3xl">
          {tier.popular ? <Highlight>{tier.name}</Highlight> : tier.name}
          {tier.popular ? (
            <Badge size="sm" className="ms-3 align-middle">
              Most popular
            </Badge>
          ) : null}
        </CardTitle>
        <CardDescription>{tier.tagline}</CardDescription>
      </CardHeader>
      <CardContent className="grid flex-1 content-start gap-6">
        <div>
          <p className="flex items-baseline gap-2.5">
            <span className="ll-num font-script text-6xl leading-none font-bold">{dollars(perMonth(tier, period))}</span>
            <span className="text-muted-foreground">{free ? "forever" : "a month"}</span>
          </p>
          <p className="mt-1 h-5 text-sm text-muted-foreground">{free ? "No card needed" : period === "yearly" ? `billed ${dollars(tier.yearly)} once a year` : "billed monthly"}</p>
        </div>
        <ul className="grid gap-2.5" aria-label={`${tier.name} includes`}>
          {tier.features.map((f) => (
            <li key={f} className="flex items-start gap-2.5">
              <Icon name="check" className="mt-1 text-green" weight={1.3} />
              <span>{f}</span>
            </li>
          ))}
        </ul>
      </CardContent>
      <CardFooter>
        <Button className="w-full" size="lg" variant={tier.popular ? "default" : "outline"} aria-pressed={chosen} onClick={onChoose}>
          {chosen ? "Picked" : tier.cta}
          {chosen ? <Icon name="check" /> : null}
        </Button>
      </CardFooter>
    </Card>
  )
}

"use client"

import * as React from "react"

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion"
import { Doodle } from "@/components/ui/doodle"
import { Paper } from "@/components/ui/paper"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { Pricing01Card } from "@/components/blocks/pricing-01/components/pricing-01-card"
import { FAQ, TIERS, dollars, type Period, type Tier } from "@/components/blocks/pricing-01/components/pricing-01-data"
import { cn } from "@/lib/utils"

type Props = {
  className?: string
  defaultPeriod?: Period
  onChoose?: (tier: Tier, period: Period) => void
}

export default function Pricing01({ className, defaultPeriod = "monthly", onChoose }: Props) {
  const [period, setPeriod] = React.useState<Period>(defaultPeriod)
  const [chosen, setChosen] = React.useState<Tier["id"] | null>(null)
  const uid = React.useId()
  const yearlySaving = TIERS.find((t) => t.popular)!
  const saved = yearlySaving.monthly * 12 - yearlySaving.yearly

  return (
    <section aria-labelledby={`${uid}-title`} className={cn("@container/pricing mx-auto grid w-full max-w-6xl gap-12 px-4 py-12 sm:px-8", className)}>
      <header className="mx-auto grid max-w-2xl justify-items-center gap-4 text-center">
        <h2 id={`${uid}-title`} className="ll-riso font-script text-5xl leading-none font-bold text-balance @lg/pricing:text-6xl">
          Pick a desk that fits
        </h2>
        <p className="text-lg text-muted-foreground text-balance">Start free with one notebook. Pay when you need more paper, more people or the good highlighters. Cancel with one press.</p>
        <div className="mt-2 flex flex-wrap items-center justify-center gap-x-3 gap-y-1">
          <ToggleGroup type="single" variant="outline" size="lg" value={period} onValueChange={(v) => v && setPeriod(v as Period)} aria-label="Billing period">
            <ToggleGroupItem value="monthly">Monthly</ToggleGroupItem>
            <ToggleGroupItem value="yearly">Yearly</ToggleGroupItem>
          </ToggleGroup>
          <span className="flex items-end gap-1 font-script text-2xl leading-none text-ink-soft">
            <Doodle name="arrow-swoop" size={48} className="-scale-x-100 rtl:scale-x-100" />
            two months free
          </span>
        </div>
      </header>

      <p role="status" className="sr-only">
        {period === "yearly" ? `Showing yearly prices. Studio saves you ${dollars(saved)} a year.` : "Showing monthly prices."}
      </p>

      <div className="mx-auto grid w-full max-w-md gap-12 pt-6 @4xl/pricing:max-w-none @4xl/pricing:grid-cols-3 @4xl/pricing:items-stretch @4xl/pricing:gap-8">
        {TIERS.map((t) => (
          <Pricing01Card
            key={t.id}
            id={`${uid}-${t.id}`}
            tier={t}
            period={period}
            chosen={chosen === t.id}
            onChoose={() => {
              setChosen(t.id)
              onChoose?.(t, period)
            }}
          />
        ))}
      </div>

      <Paper as="section" stock="slip" tilt={-0.3} seed="pricing-faq" aria-labelledby={`${uid}-faq`} className="mx-auto grid w-full max-w-2xl gap-4 px-6 py-6">
        <h3 id={`${uid}-faq`} className="font-script text-3xl leading-none font-semibold">
          Questions people ask
        </h3>
        <Accordion type="single" collapsible>
          {FAQ.map((f, i) => (
            <AccordionItem key={f.q} value={`q${i}`}>
              <AccordionTrigger>{f.q}</AccordionTrigger>
              <AccordionContent>{f.a}</AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
      </Paper>
    </section>
  )
}
